/**
 * CommentNotificationScheduler against a real Postgres (migration 1828,
 * packages/shared/src/database/migrations/1828000000000-CommentNotifications.ts).
 *
 * Generated by the /ship test coverage audit.
 * Value: protects=the sweep's claim/release/finder SQL resolves and does what the mocked spec
 * assumes (advisory lock, SKIP LOCKED claim, uuid[] release, make_interval delay, channel filter);
 * fails_when=a column, cast or predicate in that SQL is wrong (42703/42883) or a deleted comment is
 * claimed; why_new=comment-notification-scheduler.service.spec.ts mocks every query by substring,
 * so no SQL there ever reaches Postgres (Common Issue #76 is that exact shape); seam=none;
 * no_claim=webhook delivery (NotificationsService is a jest mock; owner role, not RLS).
 *
 * Runs against the local dev DB like its sibling suites; everything it writes is deleted in
 * afterAll. Fixture names are synthetic.
 */
import { randomUUID } from 'crypto';
import { DataSource } from 'typeorm';
import { AppDataSource } from '../../data-source';
import * as Entities from '../../entities';
import { CommentNotificationScheduler } from '../../modules/notifications/comment-notification-scheduler.service';

const entityClasses = Object.values(Entities).filter(
  (v): v is new () => unknown => typeof v === 'function',
);

describe('CommentNotificationScheduler against a real database', () => {
  const ds = new DataSource({
    ...(AppDataSource.options as Record<string, unknown>),
    entities: entityClasses,
    migrations: [],
  } as never);

  const suffix = randomUUID().slice(0, 8);
  const org = randomUUID();
  const sut = randomUUID();
  const optedIn = randomUUID();
  const optedOut = randomUUID();
  const runHuman = `comment-notify-spec-run-${suffix}`;
  let runUuid = '';
  const live = randomUUID();
  const newer = randomUUID();
  const deleted = randomUUID();

  const send = jest.fn();
  let scheduler: CommentNotificationScheduler;

  const notifiedAt = async (): Promise<Record<string, Date | null>> => {
    const rows: Array<{ id: string; notified_at: Date | null }> = await ds.query(
      `SELECT id, notified_at FROM test_run_comments WHERE test_run_id = $1`,
      [runUuid],
    );
    return Object.fromEntries(rows.map((r) => [r.id, r.notified_at]));
  };
  const resetUnannounced = (createdAt = '2000-01-01T00:00:00Z'): Promise<unknown> =>
    ds.query(
      `UPDATE test_run_comments SET notified_at = NULL,
              created_at = CASE WHEN id = $3 THEN $2::timestamptz + interval '1 minute' ELSE $2::timestamptz END
        WHERE test_run_id = $1`,
      [runUuid, createdAt, newer],
    );

  beforeAll(async () => {
    await ds.initialize();
    scheduler = new CommentNotificationScheduler(ds, {
      sendCommentDigest: send,
      getPerfanaUrl: () => 'https://perfana.example',
    } as never);
    await ds.query(`INSERT INTO organizations (id, name) VALUES ($1, $2)`, [org, `comment-notify-spec-${suffix}`]);
    await ds.query(
      `INSERT INTO systems_under_test (id, organization_id, name, description) VALUES ($1, $2, $3, 'spec')`,
      [sut, org, `comment-notify-spec-sut-${suffix}`],
    );
    const rows = await ds.query(
      `INSERT INTO test_runs (test_run_id, system_under_test_id, test_environment, workload, organization_id, start_time, end_time)
       VALUES ($1, $2, 'acc', 'load', $3, now(), now()) RETURNING id`,
      [runHuman, sut, org],
    );
    runUuid = rows[0].id;
    for (const [id, notify, name] of [[optedIn, true, 'in'], [optedOut, false, 'out']] as const) {
      await ds.query(
        `INSERT INTO notification_channels (id, system_under_test_id, type, name, webhook_url, notify_on_comment, enabled, organization_id)
         VALUES ($1, $2, 'slack', $3, 'https://hooks.slack.com/services/x', $4, true, $5)`,
        [id, sut, `spec-${name}`, notify, org],
      );
    }
    await ds.query(
      `INSERT INTO test_run_comments (id, test_run_id, card_key, body, author_id, author_name, organization_id, deleted_at)
       VALUES ($1, $4, 'slo', 'first', 'u-a', 'Author A', $5, NULL),
              ($2, $4, 'graphs', 'second', 'u-b', 'Author B', $5, NULL),
              ($3, $4, 'graphs', '', 'u-c', 'Author C', $5, now())`,
      [live, newer, deleted, runUuid, org],
    );
  });

  afterAll(async () => {
    await ds.query(`DELETE FROM ds_metric_collection_status WHERE test_run_id IN (SELECT test_run_id FROM test_runs WHERE id = $1)`, [runUuid]);
    await ds.query(`DELETE FROM test_runs WHERE id = $1`, [runUuid]); // cascades comments
    await ds.query(`DELETE FROM notification_channels WHERE system_under_test_id = $1`, [sut]);
    await ds.query(`DELETE FROM systems_under_test WHERE id = $1`, [sut]);
    await ds.query(`DELETE FROM organizations WHERE id = $1`, [org]);
    await ds.destroy();
  });

  beforeEach(async () => {
    send.mockReset();
    send.mockResolvedValue(undefined);
    await resetUnannounced();
  });

  it('claims the live comments, posts once to the opted-in channel only, and leaves a deleted comment alone', async () => {
    expect(await scheduler.announceRun(runUuid)).toBe(2);

    expect(send).toHaveBeenCalledTimes(1);
    const [channel, digest] = send.mock.calls[0];
    expect(channel.id).toBe(optedIn);
    expect(digest).toMatchObject({ count: 2, authorName: 'Author B', testRunId: runHuman, cardLabel: 'Graphs' });
    expect(digest.link).toBe(`https://perfana.example/test-runs/${runUuid}?card=graphs&comment=${newer}`);

    const stamps = await notifiedAt();
    expect(stamps[live]).not.toBeNull();
    expect(stamps[newer]).not.toBeNull();
    expect(stamps[deleted]).toBeNull();

    // Already announced: a second pass claims nothing.
    expect(await scheduler.announceRun(runUuid)).toBe(0);
    expect(send).toHaveBeenCalledTimes(1);
  });

  it('releases the claim for the next sweep when the only channel fails retryably', async () => {
    send.mockRejectedValue(new Error('Webhook request failed with status 503: down'));
    jest.spyOn((scheduler as never as { logger: { warn: () => void } }).logger, 'warn').mockImplementation();

    expect(await scheduler.announceRun(runUuid)).toBe(0);
    const stamps = await notifiedAt();
    expect(stamps[live]).toBeNull();
    expect(stamps[newer]).toBeNull();
  });

  it('skips a run whose advisory lock another session holds, claiming nothing', async () => {
    await ds.transaction(async (em) => {
      await em.query(`SELECT pg_advisory_xact_lock(hashtextextended('comment-notify:' || $1::text, 0))`, [runUuid]);
      expect(await scheduler.announceRun(runUuid)).toBe(0);
    });
    expect(send).not.toHaveBeenCalled();
    expect((await notifiedAt())[live]).toBeNull();
  });

  it('finds a run only once its oldest unannounced comment is past the delay', async () => {
    const announce = jest.spyOn(scheduler, 'announceRun').mockResolvedValue(0);
    try {
      await resetUnannounced(new Date().toISOString());
      await scheduler.sweep();
      expect(announce.mock.calls.map((c) => c[0])).not.toContain(runUuid);

      await resetUnannounced('2000-01-01T00:00:00Z');
      await scheduler.sweep();
      expect(announce.mock.calls.map((c) => c[0])).toContain(runUuid);
    } finally {
      announce.mockRestore();
    }
  });
});
